library ieee;use ieee.std_logic_1164.all;use std.env.all;entity testbench is end;architecture test of testbench is signal clk,reset,load:std_logic:='0';signal d,q:std_logic_vector(7 downto 0):=(others=>'0');component dut is port(clk,reset,load:in std_logic;d:in std_logic_vector(7 downto 0);q:out std_logic_vector(7 downto 0));end component;begin clk<=not clk after 5 ns;u:dut port map(clk,reset,load,d,q);process variable errors:natural:=0;procedure step(v:std_logic_vector(7 downto 0))is begin wait until falling_edge(clk);d<=v;load<='1';wait until falling_edge(clk);load<='0';wait for 1 ns;if q/=v then errors:=errors+1;report "CHECK_FAIL load mismatch" severity note;end if;end;begin reset<='1';wait until falling_edge(clk);wait until falling_edge(clk);reset<='0';step(x"00");-- TODO: add reusable checks here
step(x"A5");step(x"FF");report "CHECK_FAIL TODO" severity note;stop;wait;end process;end;
